def _tour_cost(self, tour):
    # tour: sequence of indices (list or ndarray)
    # Vectorized version using numpy advanced indexing for speed.
    t = np.asarray(tour, dtype=int)
    if t.size == 0:
        return 0.0
    dm = self.distance_matrix
    # sum distances from each city to the next, wrapping around with np.roll
    return float(dm[t, np.roll(t, -1)].sum())

def evaluate(flat_route):
    """Compute total distance of flat route (list of ints with zeros) using vectorized indexing."""
    arr = np.asarray(flat_route, dtype=int)
    if arr.size <= 1:
        return 0.0
    # Sum pairwise distances using numpy advanced indexing for speed
    return float(self.distance_matrix[arr[:-1], arr[1:]].sum())
